<?php require '../includes/functions.php';login_required();if($_SESSION['role']!=='student'){header('Location: ../admin/dashboard.php');exit;}$q=$pdo->prepare("SELECT COUNT(*) total,SUM(status='Pending') pending,SUM(status='In Progress') progress,SUM(status='Resolved') resolved FROM complaints WHERE user_id=?");$q->execute([$_SESSION['uid']]);$s=$q->fetch();$q=$pdo->prepare('SELECT c.*,k.name category FROM complaints c JOIN categories k ON k.id=c.category_id WHERE c.user_id=? ORDER BY c.created_at DESC');$q->execute([$_SESSION['uid']]);$rows=$q->fetchAll();$title='Student Dashboard';$prefix='../';require '../includes/header.php';?><section class="hero"><h1>Welcome, <?=e($_SESSION['name'])?></h1><p class="muted">Submit an issue or check your complaint progress.</p><a class="button" href="submit.php">+ Submit complaint</a></section><div class="grid"><?php foreach(['total'=>'My complaints','pending'=>'Pending','progress'=>'In progress','resolved'=>'Resolved'] as $k=>$v):?><div class="card"><div class="stat"><?= (int)($s[$k]??0)?></div><div class="muted"><?=$v?></div></div><?php endforeach;?></div><section class="panel"><h2>My complaints</h2><?php if(!$rows):?><p class="muted">No complaints submitted yet.</p><?php else:?><div class="tablebox"><table><tr><th>Title</th><th>Category</th><th>Location</th><th>Priority</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['category'])?></td><td><?=e($r['location'])?></td><td><?=e($r['priority'])?></td><td><span class="tag"><?=e($r['status'])?></span></td></tr><?php endforeach;?></table></div><?php endif;?></section><?php require '../includes/footer.php';?>
